#!/usr/bin/env python3
"""Unified diff tool based on LCS dynamic programming (difflib-free).

Exit codes follow diff(1): 0 identical, 1 differ, 2 error.
"""

import sys

CONTEXT = 3


def lcs_ops(a, b):
    """Return list of ('=', line) / ('-', line from a) / ('+', line from b).

    Classic LCS DP: dp[i][j] = LCS length of a[i:] and b[j:].
    """
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row, below = dp[i], dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = below[j + 1] + 1
            elif row[j + 1] >= below[j]:
                row[j] = row[j + 1]
            else:
                row[j] = below[j]

    ops = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            ops.append(("=", a[i]))
            i += 1
            j += 1
        elif dp[i][j + 1] >= dp[i + 1][j]:
            ops.append(("-", a[i]))
            i += 1
        else:
            ops.append(("+", b[j]))
            j += 1
    while i < n:
        ops.append(("-", a[i]))
        i += 1
    while j < m:
        ops.append(("+", b[j]))
        j += 1
    return ops


def build_groups(flat, context=CONTEXT):
    """Group op indices into change blocks padded with up to `context` equals.

    Returns a list of (start_index, end_index_exclusive) into flat.
    """
    groups = []
    n = len(flat)
    k = 0
    while k < n:
        if flat[k][0] == "=":
            k += 1
            continue
        # A change run starts at k; extend to its end.
        end = k
        while end < n and flat[end][0] != "=":
            end += 1
        start = max(0, k - context)
        while True:
            if end >= n:
                break
            # Count equals run starting at `end`.
            run_end = end
            while run_end < n and flat[run_end][0] == "=":
                run_end += 1
            gap_equals = run_end - end
            if run_end < n:
                # More changes follow after the gap.
                if gap_equals <= 2 * context:
                    end = run_end
                    while end < n and flat[end][0] != "=":
                        end += 1
                    continue
                else:
                    end += context
                    break
            else:
                end += context
                break
        end = min(end, n)
        groups.append((start, end))
        k = end
    return groups


def format_hunks(flat, path1, path2, context=CONTEXT):
    """Return formatted unified diff lines (headers plus hunks)."""
    out = ["--- " + path1, "+++ " + path2]
    for start, end in build_groups(flat, context):
        block = flat[start:end]
        a_start = sum(1 for op, _ in flat[:start] if op != "+")
        b_start = sum(1 for op, _ in flat[:start] if op != "-")
        len_a = sum(1 for op, _ in block if op != "+")
        len_b = sum(1 for op, _ in block if op != "-")
        out.append("@@ -%d,%d +%d,%d @@" % (a_start + 1, len_a, b_start + 1, len_b))
        for op, line in block:
            out.append((" " if op == "=" else op) + line)
    return out


def read_lines(path):
    with open(path, "r") as f:
        return f.read().splitlines()


def main(argv):
    if len(argv) != 3:
        sys.stderr.write("usage: udiff.py FILE1 FILE2\n")
        return 2
    path1, path2 = argv[1], argv[2]
    try:
        a = read_lines(path1)
    except OSError as e:
        sys.stderr.write("udiff.py: %s: %s\n" % (path1, e))
        return 2
    try:
        b = read_lines(path2)
    except OSError as e:
        sys.stderr.write("udiff.py: %s: %s\n" % (path2, e))
        return 2

    if a == b:
        return 0

    ops = lcs_ops(a, b)
    sys.stdout.write("\n".join(format_hunks(ops, path1, path2)) + "\n")
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

